using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using MerfitCustomerApi.Domain.Entities;
using MerfitCustomerApi.Domain.Entities.Enums;

namespace MerfitCustomerApi.Infrastructure.Configurations;

/// <summary>
/// UserDevice varliginin veritabani (Entity Framework Core) yapilandirmasini tanimlar.
/// </summary>
public class UserDeviceConfiguration : IEntityTypeConfiguration<UserDevice>
{
    /// <summary>
    /// UserDevice varligi icin tablo adi, birincil anahtar, alan kisitlari ve iliskileri yapilandirir.
    /// </summary>
    public void Configure(EntityTypeBuilder<UserDevice> builder)
    {
        // Tablo adini belirtir.
        builder.ToTable("UserDevice", "authentication");

        // Birincil anahtari tanimlar.
        builder.HasKey(x => x.Id);

        // Push bildirimleri icin cihaz jetonu.
        builder.Property(x => x.DeviceToken)
            .IsRequired(true)
            .HasMaxLength(500);

        // Cihazin isletim sistemi platformu.
        builder.Property(x => x.Platform)
            .HasConversion<string>()
            .IsRequired(true)
            .HasMaxLength(50);

        // Cihazin adi.
        builder.Property(x => x.DeviceName)
            .IsRequired(false)
            .HasMaxLength(200);

        // Cihazda yuklu uygulama surumu.
        builder.Property(x => x.AppVersion)
            .IsRequired(false)
            .HasMaxLength(300);

        // Cihazin isletim sistemi surumu.
        builder.Property(x => x.OsVersion)
            .IsRequired(false)
            .HasMaxLength(300);

        // Uygulamanin kurulum kimligi.
        builder.Property(x => x.InstallationId)
            .IsRequired(false)
            .HasMaxLength(100);

        // Pasiflestirme nedeni.
        builder.Property(x => x.DeactivationReason)
            .IsRequired(false)
            .HasMaxLength(50);

        // Bir push token ayni anda tek bir kullaniciya aittir (hesap degisiminde satir yeni kullaniciya tasinir).
        builder.HasIndex(x => x.DeviceToken).IsUnique();

        // Gondericinin kullanicinin aktif cihazlarini bulmasi icin.
        builder.HasIndex(x => new { x.UserId, x.IsActive });

        // Iliskiler (foreign key) yapilandirmasi.
        // Cihazin ait oldugu kullanicinin kimligi.
        builder.HasOne<ApplicationUser>()
            .WithMany()
            .HasForeignKey(x => x.UserId)
            .OnDelete(DeleteBehavior.Restrict);
    }
}
